CREATE SCHEMA demo;
CREATE TABLE demo.identity(persona text PRIMARY KEY CHECK(persona IN ('alice','bob')),user_id uuid UNIQUE NOT NULL REFERENCES auth.users(id),email text UNIQUE NOT NULL CHECK(email LIKE '%@example.invalid'));
INSERT INTO auth.users VALUES('d0000000-0000-4000-8000-000000000001'),('d0000000-0000-4000-8000-000000000002');
INSERT INTO demo.identity VALUES('alice','d0000000-0000-4000-8000-000000000001','alice@example.invalid'),('bob','d0000000-0000-4000-8000-000000000002','bob@example.invalid');
CREATE TABLE demo.session(token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES auth.users(id),expires_at timestamptz NOT NULL DEFAULT now()+interval '12 hours');
CREATE TABLE demo.mail(user_id uuid NOT NULL REFERENCES auth.users(id),seq bigint GENERATED ALWAYS AS IDENTITY,id text UNIQUE NOT NULL,scenario text NOT NULL,mime jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,seq));
CREATE TABLE demo.queue(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_id uuid NOT NULL,user_id uuid NOT NULL REFERENCES auth.users(id),envelope jsonb NOT NULL,status text NOT NULL DEFAULT 'PENDING',attempts int NOT NULL DEFAULT 0,available_at timestamptz NOT NULL DEFAULT now(),lease uuid,lease_until timestamptz,last_error text,duplicate boolean NOT NULL DEFAULT false,fail_once boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz);
CREATE TABLE demo.notification(event_id uuid PRIMARY KEY REFERENCES public.gmail_events(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES auth.users(id),created_at timestamptz NOT NULL DEFAULT now(),delivery_seq bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE);
CREATE TABLE demo.worker(id int PRIMARY KEY CHECK(id=1),heartbeat timestamptz NOT NULL);
GRANT USAGE ON SCHEMA demo TO hestia_backend;
GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA demo TO hestia_backend;
GRANT USAGE,SELECT ON ALL SEQUENCES IN SCHEMA demo TO hestia_backend;
